import { hash, verify } from '@node-rs/argon2'

/**
 * Passwords: argon2id (RFC 9106) – memory-hard, so stolen hashes cannot be cracked on GPUs at
 * scale. Parameters follow the second recommended option of RFC 9106 §4: 64 MiB memory,
 * 3 passes, 4 lanes (OWASP's minimum is 19 MiB/2 passes). Each hash has its own random salt
 * (16 bytes, generated by the library). Hashes with weaker parameters are upgraded on the next
 * successful login (`needsRehash`).
 *
 * At most MAX_PARALLEL hashes run at the same time (4 × 64 MiB), so a burst of logins cannot
 * exhaust the memory of the compact profile (2 GB server); the rate limits throttle further.
 */
export const PASSWORD_OPTIONS = { memoryCost: 65_536, timeCost: 3, parallelism: 4 } as const

const MAX_PARALLEL = 4
let running = 0
const waiting: (() => void)[] = []

async function limited<T>(work: () => Promise<T>): Promise<T> {
  if (running >= MAX_PARALLEL) await new Promise<void>((resolve) => waiting.push(resolve))
  running += 1
  try {
    return await work()
  } finally {
    running -= 1
    waiting.shift()?.()
  }
}

export function hashPassword(password: string): Promise<string> {
  return limited(() => hash(password, PASSWORD_OPTIONS))
}

export async function verifyPassword(passwordHash: string, password: string): Promise<boolean> {
  try {
    return await limited(() => verify(passwordHash, password))
  } catch {
    return false
  }
}

/** True when the stored hash is not argon2id or uses weaker parameters than PASSWORD_OPTIONS. */
export function needsRehash(passwordHash: string): boolean {
  const match = /^\$argon2id\$v=19\$m=(\d+),t=(\d+),p=(\d+)\$/.exec(passwordHash)
  if (!match) return true
  const [, m, t, p] = match.map(Number)
  return (
    (m as number) < PASSWORD_OPTIONS.memoryCost ||
    (t as number) < PASSWORD_OPTIONS.timeCost ||
    (p as number) < PASSWORD_OPTIONS.parallelism
  )
}

let dummyHash: Promise<string> | undefined

/** Burns the same time as a real verification, so unknown e-mails cannot be detected by timing. */
export async function verifyDummy(password: string): Promise<void> {
  dummyHash ??= hashPassword('dummy-password-for-timing')
  await verifyPassword(await dummyHash, password)
}
